  // `+INF` is read although it is written as `INF`: XSD 1.1 admits it, its
  // production being `(\+|-)?INF`, and being liberal in what we accept
  // costs nothing here.
  if (text === "INF" || text === "+INF") {
    return new OurCommon.Either<number, DeserializationError>(Infinity, null);
  }
  if (text === "-INF") {
    return new OurCommon.Either<number, DeserializationError>(-Infinity, null);
  }
  if (text === "NaN") {
    return new OurCommon.Either<number, DeserializationError>(NaN, null);
  }

  // NOTE (mristin):
  // ``Number`` is far too permissive to be trusted with the text: it reads
  // an empty string and a run of whitespace as 0, a hexadecimal, binary or
  // octal prefix as the number it spells -- ``0x10`` as 16 -- and
  // ``Infinity`` as an infinity, none of which is a valid ``xs:double``.
  //
  // See: https://www.w3.org/TR/xmlschema-2/#double
